func parseHexByte(hex string, out *uint8) (bool, error) {
	var val uint8
	for i := 0; i < len(hex); i++ {
		c := hex[i]
		var digit uint8
		switch {
		case '0' <= c && c <= '9':
			digit = c - '0'
		case 'a' <= c && c <= 'f':
			digit = c - 'a' + 10
		case 'A' <= c && c <= 'F':
			digit = c - 'A' + 10
		default:
			return false, &json.UnsupportedValueError{}
		}
		val = val*16 + digit
	}
	*out = val
	return true, nil
}

