			return nil, err
		}
		r = r*16 + r
		if err := parseHexDigit(hex[1], &g); err != nil {
			return nil, err
		}
		g = g*16 + g
		if err := parseHexDigit(hex[2], &b); err != nil {
			return nil, err
		}
